// The iTerm2 colour schemes, as the deck's five tokens.
//
// themes.json is the same file the dashboard reads, generated by
// scripts/gen-themes.py from iTerm2's own presets and from
// mbadolato/iTerm2-Color-Schemes. It is bundled rather than fetched: a phone
// on the far side of a paired deck should be able to change its colours
// without the deck answering, and 611 themes are 470 KB.

import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;
import 'package:flutter/widgets.dart';

/// The name the stock deck is published under in themes.json.
const stockThemeName = 'agents deck';

/// One colour scheme, reduced to what the deck draws with.
@immutable
class DeckTheme {
  const DeckTheme({
    required this.name,
    required this.light,
    required this.bg,
    required this.panel,
    required this.ink,
    required this.dim,
    required this.accent,
  });

  /// Reads one entry of themes.json. The deck's own token names are in there
  /// beside the dashboard's, so nothing has to be worked out here.
  factory DeckTheme.fromJson(Map<String, dynamic> json) {
    final tokens = (json['tokens'] as Map).cast<String, dynamic>();
    Color at(String key, Color fallback) {
      final hex = tokens[key];
      return hex is String ? _parseHex(hex) ?? fallback : fallback;
    }

    return DeckTheme(
      name: json['name'] as String? ?? '?',
      light: json['light'] as bool? ?? false,
      bg: at('--bg', const Color(0xFF0A0A0A)),
      panel: at('--panel', const Color(0xFF141412)),
      ink: at('--ink', const Color(0xFFE8E4DC)),
      dim: at('--dim', const Color(0xFF7A776F)),
      accent: at('--accent', const Color(0xFFFF4D00)),
    );
  }

  final String name;

  /// Whether the scheme is a light one. Only used to label it in the picker.
  final bool light;

  final Color bg;
  final Color panel;
  final Color ink;
  final Color dim;
  final Color accent;
}

Color? _parseHex(String s) {
  final hex = s.startsWith('#') ? s.substring(1) : s;
  if (hex.length != 6) return null;
  final v = int.tryParse(hex, radix: 16);
  return v == null ? null : Color(0xFF000000 | v);
}

List<DeckTheme>? _catalogue;

/// Every theme, in the order themes.json lists them (the stock deck first,
/// then the rest by name). Read once and kept.
Future<List<DeckTheme>> deckThemes() async {
  final had = _catalogue;
  if (had != null) return had;
  final raw = await rootBundle.loadString(
    'packages/agents_deck_ui/assets/themes.json',
  );
  final json = jsonDecode(raw) as Map<String, dynamic>;
  final list = [
    for (final t in json['themes'] as List)
      DeckTheme.fromJson((t as Map).cast<String, dynamic>()),
  ];
  return _catalogue = list;
}

/// The theme called [name], or null if nothing is called that. A missing
/// theme is not an error: the file is regenerated as schemes are published,
/// and a name saved by an older build may no longer be in it.
Future<DeckTheme?> deckTheme(String? name) async {
  if (name == null || name == stockThemeName) return null;
  for (final t in await deckThemes()) {
    if (t.name == name) return t;
  }
  return null;
}
